import java.util.*;class Solution{interface Tx{void begin();void insert(String id,int amount);void commit();void rollback();}static void run(List<String>rows,Tx tx){List<Map.Entry<String,Integer>>parsed=new ArrayList<>();for(String row:rows){String[]p=row.split(":",-1);if(p.length!=2||p[0].isBlank())throw new IllegalArgumentException("row");int amount=Integer.parseInt(p[1]);if(amount<0)throw new IllegalArgumentException("amount");parsed.add(Map.entry(p[0],amount));}tx.begin();try{for(var entry:parsed)tx.insert(entry.getKey(),entry.getValue());tx.commit();}catch(RuntimeException error){tx.rollback();throw error;}}}
